(()=>{
'use strict';
const $=id=>document.getElementById(id);
const icon=(name)=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const safeUrl=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}};
const toDate=value=>{if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'})};
const toTime=value=>{if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?'—':d.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})};
const TODAY=()=>new Date().toISOString().slice(0,10);
const STATUS=['todo','doing','review','done'];
const STATUS_NAME={todo:'待开始',doing:'进行中',review:'待验收',done:'已完成'};
const PRIORITY={normal:'普通',important:'重点',urgent:'加急'};
const PRIORITY_SCORE={urgent:0,important:1,normal:2};
const ROLE_NAME={admin:'全局管理员',operator:'运营负责人',developer:'开发成员',viewer:'只读成员'};
const BUCKET='requirements-private';
let db=null,me=null,globalRole=null,projects=[],memberships=new Map(),projectId='',iterations=[],categories=[],requirements=[],assets=[],progress=new Map(),members=[],activity=[],signed=new Map();
let activeTaskId='',detailTab='details',editingTaskId='',editingProjectId='',editingCategoryId='',editingIterationId='',moveTaskId='',previewPaths=[],previewIndex=0;
let pollTimer=null,toastTimer=null,loadingProject=false,isBusy=false,authMode='login',sessionId='',sessionSerial=0,dragTaskId='',confirmAction=null;
const state={category:'all',iteration:'',view:'all',status:'all',sort:'plan',query:'',settingsTab:'projects'};
const project=()=>projects.find(p=>p.id===projectId);
const projectRole=()=>globalRole==='admin'?'admin':memberships.get(projectId)||null;
const canEdit=()=>['admin','operator'].includes(projectRole());
const canProgress=()=>['admin','operator','developer'].includes(projectRole());
const canManage=()=>canEdit();
const isAdmin=()=>globalRole==='admin';
const canCreateProject=()=>isAdmin()||globalRole==='operator'||[...memberships.values()].includes('operator');
const taskById=id=>requirements.find(t=>t.id===id);
const prog=id=>progress.get(id)||{status:'todo',is_blocked:false,note:''};
const status=id=>STATUS.includes(prog(id).status)?prog(id).status:'todo';
const iteration=()=>iterations.find(b=>b.id===state.iteration)||null;
const iterationName=id=>iterations.find(b=>b.id===id)?.name||'未命名批次';
const orderedIterations=()=>[...iterations].sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))||String(b.id).localeCompare(String(a.id)));
const latestOpenIteration=()=>orderedIterations().find(b=>!b.is_closed)||null;
const batchTasks=()=>state.iteration==='all'?requirements:requirements.filter(t=>t.iteration_id===state.iteration);
const unwithdrawn=()=>batchTasks().filter(t=>!t.is_withdrawn);
const priorityRank=t=>PRIORITY_SCORE[t.priority]??2;
const planCompare=(a,b)=>(a.sort_order??999999)-(b.sort_order??999999)||String(a.created_at||'').localeCompare(String(b.created_at||''))||String(a.id).localeCompare(String(b.id));
const iterationRank=t=>orderedIterations().findIndex(b=>b.id===t.iteration_id);
const manualTasks=()=>[...batchTasks()].sort((a,b)=>iterationRank(a)-iterationRank(b)||priorityRank(a)-priorityRank(b)||planCompare(a,b));
const taskGroup=t=>[...requirements].filter(x=>x.iteration_id===t.iteration_id&&x.priority===t.priority).sort(planCompare);
const canReorder=()=>canEdit()&&!!iteration()&&!iteration().is_closed&&state.view==='all'&&state.category==='all'&&state.status==='all'&&state.sort==='plan'&&!state.query;
const isOverdue=t=>Boolean(t.due_date&&t.due_date<TODAY()&&!t.is_withdrawn&&status(t.id)!=='done');
const projectStored=()=>{try{return localStorage.getItem('board-project-v4')}catch{return null}};
const saveProject=id=>{try{localStorage.setItem('board-project-v4',id)}catch{}};
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3700)}
function fail(error,prefix='操作失败'){console.error(prefix,error);toast(`${prefix}：${error?.message||error}`)}
function showScreen(screen){$('shell').hidden=screen!=='app';$('authScreen').hidden=screen!=='auth';$('deniedScreen').hidden=screen!=='denied'}
function setSync(ok,text){$('syncLight').classList.toggle('fail',!ok);$('syncText').textContent=text||(ok?'团队数据已同步':'暂时无法同步')}
function openModal(id){const d=$(id);if(!d.open)d.showModal()}
function closeModal(id){const d=$(id);if(d.open)d.close()}
function closeSidebar(){$('sidebar').classList.remove('open');$('sidebarShade').hidden=true}
function openSidebar(){$('sidebar').classList.add('open');$('sidebarShade').hidden=false}
function resetData(){clearInterval(pollTimer);pollTimer=null;projects=[];memberships.clear();projectId='';iterations=[];state.iteration='';categories=[];requirements=[];assets=[];progress.clear();members=[];activity=[];signed.clear();activeTaskId='';me=null;globalRole=null;sessionId='';closeDrawer();closeSidebar()}
function stats(){const list=unwithdrawn();return{total:list.length,todo:list.filter(t=>status(t.id)==='todo').length,doing:list.filter(t=>status(t.id)==='doing').length,review:list.filter(t=>status(t.id)==='review').length,done:list.filter(t=>status(t.id)==='done').length,blocked:list.filter(t=>prog(t.id).is_blocked).length,urgent:list.filter(t=>t.priority==='urgent'&&status(t.id)!=='done').length,overdue:list.filter(isOverdue).length}}
function userBadge(){const role=projectRole();$('userName').textContent=me?.email||'未登录';$('userRole').textContent=ROLE_NAME[role]||ROLE_NAME[globalRole]||'未授权';$('userAvatar').textContent=(me?.email||'U').charAt(0).toUpperCase();$('addTaskBtn').hidden=!canEdit();$('settingsBtn').hidden=!canManage();$('createProjectQuick').hidden=!canCreateProject();$('sidebarSettings').hidden=!canManage()}
async function authRoute(session){const seq=++sessionSerial;if(!session?.user){resetData();showScreen('auth');return}if(session.user.id===sessionId&&projects.length)return;
 try{me=session.user;sessionId=me.id;await loadAccess();if(seq!==sessionSerial)return;if(!projects.length){if(canCreateProject()){projectId='';categories=[];requirements=[];assets=[];members=[];progress.clear();showScreen('app');renderAll();setSync(true,'尚无项目，点击左侧＋创建');return}$('deniedMessage').textContent=`${me.email} 已登录，但尚未获得任何项目的权限。请联系管理员或项目负责人。`;showScreen('denied');return}showScreen('app');await loadProject(projectStored()&&projects.some(p=>p.id===projectStored())?projectStored():projects[0].id);startPolling()}
 catch(e){if(seq!==sessionSerial)return;console.error('authRoute',e);if(/board_projects|schema cache|does not exist/i.test(e.message||'')){$('deniedMessage').textContent='数据库还未升级到 V4.1。请先执行 V4.1 迁移 SQL，再刷新网页。'}else{$('deniedMessage').textContent=`无法读取项目权限：${e.message||e}`;}showScreen('denied')}}
async function loadAccess(){const email=String(me?.email||'').toLowerCase();if(!email)throw Error('当前账号没有邮箱');const [userRes,projectsRes,membersRes]=await Promise.all([
 db.from('team_members').select('email,role').eq('email',email).maybeSingle(),
 db.from('board_projects').select('*').order('created_at',{ascending:true}),
 db.from('board_project_members').select('project_id,email,role').eq('email',email)
]);for(const r of [userRes,projectsRes,membersRes])if(r.error)throw r.error;
 globalRole=userRes.data?.role||null;projects=projectsRes.data||[];memberships=new Map((membersRes.data||[]).map(x=>[x.project_id,x.role]));
 if(!globalRole&&!projects.length)return;
 // A project membership is the only access path for non-admins.
 if(!isAdmin())projects=projects.filter(p=>memberships.has(p.id)&&!p.is_archived);
}
async function loadProject(id,{quiet=false}={}){if(!projects.some(p=>p.id===id))return;const changed=id!==projectId;projectId=id;saveProject(id);loadingProject=true;
 if(changed){state.iteration='';state.category='all';state.view='all';state.status='all';state.query='';state.sort='plan';$('searchInput').value='';$('statusFilter').value='all';$('sortSelect').value='plan';closeDrawer();signed.clear();}
 try{const [taskRes,progRes,categoryRes,memberRes,assetRes,iterationRes]=await Promise.all([
  db.from('requirements').select('*').eq('project_id',id).order('sort_order',{ascending:true}),
  db.from('requirement_progress').select('*').eq('project_id',id),
  db.from('board_categories').select('*').eq('project_id',id).order('sort_order',{ascending:true}),
  db.from('board_project_members').select('project_id,email,role,created_at').eq('project_id',id).order('created_at',{ascending:true}),
  db.from('board_assets').select('id,label,path').eq('project_id',id).order('sort_order',{ascending:true}),
  db.from('board_iterations').select('*').eq('project_id',id).order('created_at',{ascending:false})
 ]);for(const r of [taskRes,progRes,categoryRes,memberRes,assetRes,iterationRes])if(r.error)throw r.error;
 if(id!==projectId)return;requirements=taskRes.data||[];progress=new Map((progRes.data||[]).map(x=>[x.requirement_id,x]));categories=categoryRes.data||[];members=memberRes.data||[];assets=assetRes.data||[];iterations=iterationRes.data||[];
 if(state.iteration!=='all'&&!iterations.some(b=>b.id===state.iteration))state.iteration=(latestOpenIteration()||orderedIterations()[0])?.id||'all';
 renderAll();setSync(true,'团队数据已同步');if(!quiet)window.scrollTo({top:0,behavior:'instant'});
 }catch(e){setSync(false,'同步失败');if(!quiet)fail(e,'加载项目失败')}finally{loadingProject=false}}
function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{if(document.hidden||loadingProject||isBusy||!projectId)return;try{const oldProject=projectId;await loadAccess();if(!projects.some(p=>p.id===oldProject)){showScreen('denied');$('deniedMessage').textContent='你已被移出当前项目，请重新检查权限。';return}if(projectId!==oldProject)return;await loadProject(oldProject,{quiet:true})}catch(e){setSync(false,'自动同步受阻');console.error(e)}},20000)}
async function switchProject(id){if(!projects.some(p=>p.id===id))return;await loadProject(id);closeSidebar()}
function renderAll(){userBadge();renderProjectNav();renderIterationToolbar();renderCategoryNav();renderSummary();renderViewTabs();renderTaskList();$('projectHeading').textContent=project()?.name||'项目需求';$('breadcrumbProject').textContent=project()?.name||'项目';$('projectDescriptionText').textContent=project()?.description||'运营安排需求、开发记录进度，所有成员保持同步。';$('projectCount').textContent=`${requirements.length} 项`;const mobile=$('mobileProjectSelect');mobile.innerHTML=projects.map(p=>`<option value="${escapeHtml(p.id)}" ${p.id===projectId?'selected':''}>${escapeHtml(p.name)}</option>`).join('');mobile.disabled=projects.length<2}
function renderIterationToolbar(){const selected=iteration();$('iterationSelect').innerHTML=orderedIterations().map(b=>`<option value="${escapeHtml(b.id)}" ${state.iteration===b.id?'selected':''}>${escapeHtml(b.name)}${b.is_closed?' · 已结束':''}</option>`).join('')+`<option value="all" ${state.iteration==='all'?'selected':''}>全部批次（历史汇总）</option>`;$('iterationSelect').disabled=!iterations.length;
 $('iterationBadge').textContent=selected?(selected.is_closed?'已结束批次':'进行中批次'):'跨批次汇总';$('iterationBadge').className='iteration-status '+(selected?.is_closed?'closed':'');
 const total=batchTasks().length;$('iterationCaption').textContent=selected?`${total} 条需求 · ${selected.description||'本批次需求独立统计、排序和导出'}`:`${iterations.length} 个批次 · 汇总 ${total} 条需求`;
 $('iterationManage').hidden=!canEdit();$('iterationNew').hidden=!canEdit();$('iterationNew').disabled=!canEdit();}
function renderProjectNav(){$('projectNav').innerHTML=projects.map(p=>`<button class="side-item ${p.id===projectId?'active':''}" type="button" data-project="${escapeHtml(p.id)}">${icon('folder')}<span>${escapeHtml(p.name)}${p.is_archived?'（归档）':''}</span></button>`).join('')}
function allCategories(){const list=[...categories];for(const t of requirements){if(!list.some(c=>c.name===t.category))list.push({id:'legacy:'+t.category,name:t.category,sort_order:999999,is_active:false})}return list.sort((a,b)=>(a.sort_order??999999)-(b.sort_order??999999)||a.name.localeCompare(b.name))}
function renderCategoryNav(){const tasks=batchTasks();const items=[{name:'all',display:'全部需求',count:tasks.length},...allCategories().filter(c=>c.is_active||tasks.some(t=>t.category===c.name)).map(c=>({name:c.name,display:c.name,count:tasks.filter(t=>t.category===c.name).length}))];$('categoryNav').innerHTML=items.map(c=>`<button type="button" class="side-item ${state.category===c.name?'active':''}" data-category="${escapeHtml(c.name)}">${icon(c.name==='all'?'grid':'note')}<span>${escapeHtml(c.display)}</span><em>${c.count}</em></button>`).join('');$('assetCount').textContent=assets.length;$('assetsNav').classList.toggle('active',state.category==='assets')}
function renderSummary(){const s=stats(),percent=s.total?Math.round(s.done/s.total*100):0,scope=iteration()?'当前批次':'所有批次';$('summary').innerHTML=`<div class="summary-card main-metric"><div class="summary-label">${scope}完成率</div><div class="summary-value">${percent}<small style="font-size:16px">%</small></div><div class="summary-detail">${s.done} / ${s.total} 项已通过验收 · ${s.urgent} 项加急</div><div class="progress-track"><i style="width:${percent}%"></i></div></div>${[['全部任务',s.total,'grid',''],['进行中',s.doing,'clock',''],['待验收',s.review,'flag','review'],['已完成',s.done,'check','done']].map(x=>`<div class="summary-card ${x[3]}"><div class="summary-label">${icon(x[2])}${x[0]}</div><div class="summary-value">${x[1]}</div><div class="summary-detail">${x[0]==='全部任务'?`${s.blocked} 项阻塞 · ${s.overdue} 项逾期`:x[0]==='已完成'?'运营已确认验收':'本批次任务统计'}</div></div>`).join('')}`}
function renderViewTabs(){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-pressed',String(b.dataset.view===state.view))})}
function listedTasks(){let data=batchTasks().filter(t=>{if(state.category!=='all'&&t.category!==state.category)return false;if(state.view==='mine'&&t.assignee_email!==me?.email?.toLowerCase())return false;if(state.view==='review'&&(status(t.id)!=='review'||t.is_withdrawn))return false;if(state.view==='focus'&&(!['urgent','important'].includes(t.priority)||t.is_withdrawn))return false;if(state.status==='blocked'&&!prog(t.id).is_blocked)return false;if(state.status!=='blocked'&&state.status!=='all'&&status(t.id)!==state.status)return false;const q=state.query.toLowerCase().trim();return !q||`${t.title} ${t.description} ${t.category} ${t.assignee_email||''}`.toLowerCase().includes(q)});
 // Batch (newest first), then priority (urgent / important / normal), then chosen secondary order.
 const secondary=(a,b)=>state.sort==='updated'?String(b.updated_at||'').localeCompare(String(a.updated_at||''))||planCompare(a,b):state.sort==='due'?String(a.due_date||'9999').localeCompare(String(b.due_date||'9999'))||planCompare(a,b):planCompare(a,b);
 data.sort((a,b)=>iterationRank(a)-iterationRank(b)||priorityRank(a)-priorityRank(b)||secondary(a,b));return data}
function taskTags(t,showPriority=true){return `<span class="mini-tag">${escapeHtml(t.category)}</span>${showPriority&&t.priority&&t.priority!=='normal'?`<span class="mini-tag priority-${t.priority}">${PRIORITY[t.priority]}</span>`:''}<span class="mini-tag status-${status(t.id)}">${STATUS_NAME[status(t.id)]}</span>${prog(t.id).is_blocked?`<span class="mini-tag blocked">阻塞</span>`:''}${t.is_withdrawn?`<span class="mini-tag blocked">已撤回</span>`:''}`}
function renderTaskList(){const isAssets=state.category==='assets';$('taskSectionTitle').textContent=isAssets?'其他参考素材':'需求列表';$('viewTabs').hidden=isAssets;document.querySelector('.toolbar').hidden=isAssets;if(isAssets){renderAssets();return}const tasks=listedTasks();$('listTotal').textContent=`${tasks.length} 项`;
 if(!tasks.length){$('taskList').innerHTML=`<div class="empty-state">${icon('search')}<h3>${batchTasks().length?'没有匹配的需求':'当前批次还没有需求'}</h3><p>${batchTasks().length?'调整筛选条件，或切换其他批次查看。':'运营可以创建新需求；历史批次可以通过上方选择器查看。'}</p>${canEdit()&&!batchTasks().length?'<button type="button" class="btn btn-dark" data-empty-add>＋ 添加需求</button>':''}</div>`;return}
 let previous='';$('taskList').innerHTML=tasks.map(t=>{let section='';if(state.iteration==='all'&&t.iteration_id!==previous){previous=t.iteration_id;const b=iterations.find(x=>x.id===t.iteration_id);section=`<div class="batch-list-heading">${icon('folder')}<span>${escapeHtml(iterationName(t.iteration_id))}</span><small>${b?.is_closed?'已结束':'进行中'}</small></div>`}
 const group=taskGroup(t),order=group.findIndex(x=>x.id===t.id)+1,pr=t.priority||'normal';const priControl=canEdit()?`<label class="priority-inline priority-${escapeHtml(pr)}"><span>优先级</span><select data-priority="${escapeHtml(t.id)}" aria-label="调整 ${escapeHtml(t.title)} 的优先级"><option value="normal" ${pr==='normal'?'selected':''}>普通</option><option value="important" ${pr==='important'?'selected':''}>重点</option><option value="urgent" ${pr==='urgent'?'selected':''}>加急</option></select></label>`:`<span class="priority-readonly priority-${escapeHtml(pr)}">${PRIORITY[pr]||'普通'}</span>`;
 return `${section}<article class="task-card ${pr==='urgent'?'is-urgent':''}" data-task-card="${escapeHtml(t.id)}" ${canReorder()?'draggable="true"':''}><div class="task-row"><div class="task-index" title="本批次·同优先级组内第 ${order} 位">${String(order).padStart(2,'0')}</div><div class="task-info"><div class="task-badges">${taskTags(t,false)}</div><button type="button" class="task-title" data-open="${escapeHtml(t.id)}">${escapeHtml(t.title)}</button><p class="task-excerpt">${escapeHtml((t.description||'暂无需求说明').replace(/\s+/g,' ').slice(0,120))}</p><div class="task-meta">${t.assignee_email?`<span>${icon('user')}${escapeHtml(t.assignee_email)}</span>`:'<span>未指定负责人</span>'}${t.due_date?`<span class="${isOverdue(t)?'late':''}">${icon('calendar')}${escapeHtml(t.due_date)}${isOverdue(t)?' · 已逾期':''}</span>`:''}<span>${icon('clock')}更新 ${toTime(prog(t.id).updated_at||t.updated_at)}</span></div></div><div class="task-actions">${priControl}${canEdit()?`<button type="button" class="btn btn-light" title="调整本优先级内的执行顺序" data-move="${escapeHtml(t.id)}" ${iterations.find(b=>b.id===t.iteration_id)?.is_closed?'disabled':''}>顺序</button>`:''}<button type="button" class="btn btn-light" data-open="${escapeHtml(t.id)}">详情 ${icon('right')}</button>${canReorder()?`<button type="button" class="drag-handle" title="仅在同一优先级内拖动" aria-label="拖动调整同优先级顺序">${icon('grip')}</button>`:''}</div></div></article>`}).join('')}
async function renderAssets(){$('listTotal').textContent=`${assets.length} 张`;$('taskList').innerHTML=assets.length?`<div class="detail-images" style="grid-template-columns:repeat(auto-fill,minmax(180px,1fr))">${assets.map(a=>`<button type="button" class="detail-image" data-asset-preview="${escapeHtml(a.path)}"><img loading="lazy" src="${escapeHtml(signedSrc(a.path))}" alt="${escapeHtml(a.label)}"><span>${escapeHtml(a.label)}</span></button>`).join('')}</div>`:'<div class="empty-state">暂无独立参考素材</div>';await ensureSigned(assets.map(x=>x.path));if(state.category==='assets')$('taskList').querySelectorAll('[data-asset-preview]').forEach(b=>{const im=b.querySelector('img');if(im)im.src=signedSrc(b.dataset.assetPreview)})}
function closeDrawer(){$('taskDrawer').hidden=true;$('drawerBackdrop').hidden=true;document.body.style.overflow='';activeTaskId='';activity=[]}
async function openTask(id){if(!taskById(id))return;activeTaskId=id;detailTab='details';$('drawerBackdrop').hidden=false;$('taskDrawer').hidden=false;document.body.style.overflow='hidden';renderDrawer();const t=taskById(id);await ensureSigned([...(t.sources||[]),...(t.references||[])]);if(activeTaskId===id&&detailTab==='details')renderDrawerBody()}
function renderDrawer(){const t=taskById(activeTaskId);if(!t){closeDrawer();return}const p=prog(t.id);$('drawerTop').innerHTML=`<div class="task-badges">${taskTags(t)}</div><h2>${escapeHtml(t.title)}</h2><div class="task-meta"><span>${icon('user')}${escapeHtml(t.assignee_email||'未指定开发负责人')}</span>${t.due_date?`<span class="${isOverdue(t)?'late':''}">${icon('calendar')}${escapeHtml(t.due_date)}</span>`:''}<span>${icon('clock')}更新于 ${toTime(p.updated_at||t.updated_at)}</span></div>`;document.querySelectorAll('#drawerTabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===detailTab));renderDrawerBody();renderDrawerActions()}
function detailImages(t){return [...new Set([...(t.sources||[]),...(t.references||[])])]}
function signedSrc(path){const entry=signed.get(path);return entry&&entry.expires>Date.now()?entry.url:''}
async function ensureSigned(paths){const clean=[...new Set(paths||[])].filter(Boolean).filter(p=>!signedSrc(p));if(!clean.length)return;await Promise.all(clean.map(async path=>{try{const {data,error}=await db.storage.from(BUCKET).createSignedUrl(path,600);if(!error&&data?.signedUrl)signed.set(path,{url:data.signedUrl,expires:Date.now()+540000})}catch(e){console.warn('Preview unavailable',e)}}))}
function renderDrawerBody(){const t=taskById(activeTaskId);if(!t)return;if(detailTab==='activity'){renderActivityBody();return}const urls=(t.links||[]).map(u=>{const link=safeUrl(u);if(!link)return '';return `<a href="${escapeHtml(link)}" target="_blank" rel="noopener noreferrer">${icon('external')}<span>${escapeHtml(link)}</span></a>`}).join('');const pics=detailImages(t);$('drawerBody').innerHTML=`${t.is_withdrawn?'<div class="role-explainer">这条需求已撤回，暂不进行开发。运营可以恢复后继续处理。</div>':''}<section class="detail-block"><h3 class="detail-heading">需求说明与验收标准</h3><div class="detail-description">${escapeHtml(t.description||'运营暂未补充需求说明。')}</div></section>${urls?`<section class="detail-block"><h3 class="detail-heading">参考网站</h3><div class="detail-links">${urls}</div></section>`:''}${pics.length?`<section class="detail-block"><h3 class="detail-heading">参考图片 · ${pics.length} 张</h3><div class="detail-images">${pics.map((path,i)=>`<button type="button" class="detail-image" data-image="${escapeHtml(path)}"><img loading="lazy" src="${escapeHtml(signedSrc(path))}" alt="需求参考图 ${i+1}"><span>点击放大查看</span></button>`).join('')}</div></section>`:''}<section class="detail-block"><h3 class="detail-heading">计划信息</h3><div class="role-explainer">所属批次：${escapeHtml(iterationName(t.iteration_id))}<br>同优先级组顺序：第 ${taskGroup(t).findIndex(x=>x.id===t.id)+1} 位 · 优先级：${PRIORITY[t.priority]||'普通'} · 截止日期：${escapeHtml(t.due_date||'未设置')}<br>原始分类：${escapeHtml(t.category)} · 创建：${toDate(t.created_at)}</div></section>`}
function renderDrawerActions(){const t=taskById(activeTaskId);if(!t)return;const current=status(t.id);let actionButton='';if(canProgress()&&!t.is_withdrawn){if(projectRole()==='developer'&&current==='todo')actionButton=`<button type="button" class="btn btn-dark" data-quick="doing">开始处理</button>`;else if(projectRole()==='developer'&&current==='doing')actionButton=`<button type="button" class="btn btn-dark" data-quick="review">提交待验收</button>`;else if(canEdit()&&current==='review')actionButton=`<button type="button" class="btn btn-light" data-return>退回修改</button><button type="button" class="btn btn-dark" data-quick="done">验收通过</button>`;else if(canEdit()&&current==='done')actionButton=`<button type="button" class="btn btn-light" data-quick="doing">重新打开</button>`}
 $('drawerActions').innerHTML=`<button type="button" class="btn btn-light" id="drawerHistory">${icon('message')}进度记录</button>${canEdit()?`<button type="button" class="btn btn-light" data-drawer-edit="${escapeHtml(t.id)}">编辑需求</button><button type="button" class="btn btn-light" data-drawer-move="${escapeHtml(t.id)}" ${iterations.find(b=>b.id===t.iteration_id)?.is_closed?'disabled':''}>调整排序</button>`:''}${canEdit()?`<button type="button" class="btn btn-light" data-withdraw>${t.is_withdrawn?'恢复':'撤回'}</button>`:''}${isAdmin()?`<button type="button" class="btn btn-outline-red" data-delete>删除</button>`:''}${actionButton}`}

async function loadActivity(){const id=activeTaskId;if(!id)return;const {data,error}=await db.from('board_activity').select('*').eq('project_id',projectId).eq('requirement_id',id).order('created_at',{ascending:false}).limit(100);if(error)throw error;if(activeTaskId!==id)return;activity=data||[];const imagePaths=activity.flatMap(a=>a.attachment_paths||[]);await ensureSigned(imagePaths);if(activeTaskId===id&&detailTab==='activity')renderDrawerBody()}
function renderActivityBody(){const t=taskById(activeTaskId);if(!t)return;const p=prog(t.id);const canWrite=canProgress()&&!t.is_withdrawn;const allowedStatuses=STATUS.filter(s=>s!=='done'||canEdit());const statusOptions=allowedStatuses.map(x=>`<option value="${x}" ${status(t.id)===x?'selected':''}>${STATUS_NAME[x]}</option>`).join('');let cards=activity.map(a=>{const data=a.metadata||{};let heading=a.kind==='status'?`更新进度：${STATUS_NAME[data.after]||'状态已更新'}`:a.kind==='requirement'?'需求信息有调整':'追加进度反馈';const paths=a.attachment_paths||[];const link=safeUrl(a.link);const changeText=a.kind==='requirement'?(data.priority?'优先级已调整 · ':data.withdrawn?data.withdrawn[1]?'需求已撤回 · ':'需求已恢复 · ':'')+(data.assignee?'开发负责人已调整 · ':'')+(data.position_changed?'执行顺序已调整':''):'';return `<div class="timeline-entry"><h4>${escapeHtml(heading)}</h4><small>${escapeHtml(a.actor_email)} · ${toTime(a.created_at)}</small>${a.body?`<p>${escapeHtml(a.body)}</p>`:''}${changeText?`<p>${escapeHtml(changeText)}</p>`:''}${a.kind==='status'?`<p>从 ${STATUS_NAME[data.before]||'待开始'} → ${STATUS_NAME[data.after]||'待开始'}${data.blocked_after?' · 当前阻塞':''}</p>`:''}${paths.length?`<div class="timeline-photos">${paths.map(path=>`<button type="button" data-image="${escapeHtml(path)}"><img src="${escapeHtml(signedSrc(path))}" alt="进度图片"></button>`).join('')}</div>`:''}${link?`<a href="${escapeHtml(link)}" target="_blank" rel="noopener noreferrer">打开成果链接 ↗</a>`:''}</div>`}).join('');if(p.note)cards+=`<div class="timeline-entry"><h4>旧版开发备注</h4><small>迁移前保留的内容</small><p>${escapeHtml(p.note)}</p></div>`;
 $('drawerBody').innerHTML=`${canWrite?`<div class="progress-action-card"><div class="action-head"><h4>更新工作进度</h4><span class="mini-tag status-${status(t.id)}">${STATUS_NAME[status(t.id)]}</span></div><form id="progressForm" class="progress-form"><select id="progressStatus" aria-label="选择进度状态">${statusOptions}</select><label class="checkbox-line"><input type="checkbox" id="progressBlocked" ${p.is_blocked?'checked':''}>任务受阻（等待资料、依赖或其他原因）</label><textarea id="progressMessage" maxlength="4000" placeholder="本次进度说明（遇到问题、完成内容或退回原因）"></textarea><button type="submit" class="btn btn-dark">保存进度</button></form></div><div class="progress-action-card"><div class="action-head"><h4>添加开发记录 / 完成截图</h4></div><form id="commentForm" class="progress-form"><textarea id="commentBody" maxlength="4000" placeholder="例如：已优化移动端排版，截图如下…"></textarea><input id="commentLink" type="url" placeholder="成果链接（可选）"><div class="field"><label for="commentImages">上传截图（最多 5 张，单张 10MB）</label><input type="file" id="commentImages" accept="image/png,image/jpeg,image/webp" multiple></div><button type="submit" class="btn btn-light">发布进度记录</button></form></div>`:''}<h3 class="detail-heading">历史记录 · ${activity.length} 条</h3>${cards?`<div class="timeline">${cards}</div>`:'<div class="time-empty">还没有进度记录，开发开始工作后这里会自动形成时间线。</div>'}`;
 if(canWrite){$('progressForm').addEventListener('submit',saveProgress);$('commentForm').addEventListener('submit',addComment)}}
async function uploadImages(files){const list=[...files];if(!list.length)return[];if(list.length>8)throw Error('单次最多上传 8 张图片');const paths=[];for(const file of list){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('仅支持 JPG/PNG/WebP，单张不超过 10MB');const ext=file.type==='image/jpeg'?'jpg':file.type==='image/png'?'png':'webp';const path=`projects/${projectId}/uploads/${crypto.randomUUID()}.${ext}`;const {error}=await db.storage.from(BUCKET).upload(path,file,{cacheControl:'3600',contentType:file.type,upsert:false});if(error)throw error;paths.push(path)}return paths}
async function saveProgress(e){e.preventDefault();if(!canProgress()||!activeTaskId)return;const form=e.currentTarget,b=form.querySelector('button[type=submit]'),next=$('progressStatus').value,blocked=$('progressBlocked').checked,note=$('progressMessage').value.trim();if(blocked&&!prog(activeTaskId).is_blocked&&!note){toast('开启阻塞时请填写原因');$('progressMessage').focus();return}b.disabled=true;isBusy=true;try{const {error}=await db.rpc('board_transition_task',{p_task:activeTaskId,p_status:next,p_blocked:blocked,p_note:note});if(error)throw error;await loadProject(projectId,{quiet:true});await loadActivity();toast('进度已保存并记录到时间线')}catch(err){fail(err,'更新进度失败')}finally{isBusy=false;b.disabled=false}}
async function addComment(e){e.preventDefault();if(!canProgress()||!activeTaskId)return;const form=e.currentTarget,b=form.querySelector('button[type=submit]'),body=$('commentBody').value.trim(),link=$('commentLink').value.trim(),files=$('commentImages').files;if(!body&&!link&&!files.length){toast('请输入备注、上传截图或添加成果链接');return}if(files.length>5){toast('最多上传 5 张截图');return}b.disabled=true;isBusy=true;try{const paths=await uploadImages(files);const {error}=await db.rpc('board_add_comment',{p_task:activeTaskId,p_body:body,p_paths:paths,p_link:link||null});if(error)throw error;await loadActivity();toast('进度记录已发布')}catch(err){fail(err,'提交记录失败')}finally{isBusy=false;b.disabled=false}}
async function quickStatus(value){if(!canProgress()||!activeTaskId)return;isBusy=true;try{const {error}=await db.rpc('board_transition_task',{p_task:activeTaskId,p_status:value,p_blocked:false,p_note:''});if(error)throw error;await loadProject(projectId,{quiet:true});detailTab='activity';await loadActivity();renderDrawer();toast(value==='done'?'已通过验收':'状态已更新')}catch(e){fail(e,'修改状态失败')}finally{isBusy=false}}
async function openActivity(){detailTab='activity';renderDrawer();try{await loadActivity()}catch(e){fail(e,'加载进度记录失败')}}
async function openImage(path){const paths=activeTaskId?Array.from(new Set([...detailImages(taskById(activeTaskId)),...activity.flatMap(a=>a.attachment_paths||[])])):[];previewPaths=paths.includes(path)?paths:[path];previewIndex=previewPaths.indexOf(path);await paintImage();openModal('previewDialog')}
async function paintImage(){const path=previewPaths[previewIndex];if(!path)return;await ensureSigned([path]);$('previewImage').src=signedSrc(path);$('previewCount').textContent=`${previewIndex+1} / ${previewPaths.length}`;$('previewPrev').disabled=previewIndex===0;$('previewNext').disabled=previewIndex===previewPaths.length-1}
function editorCategories(current){return allCategories().filter(c=>c.is_active||c.name===current).map(c=>`<option value="${escapeHtml(c.name)}">${escapeHtml(c.name)}${c.is_active?'':'（停用）'}</option>`).join('')}
async function openEditor(id=null){if(!canEdit())return;const t=id?taskById(id):null;if(!categories.length){toast('请先到项目设置中添加需求分类');openSettings('categories');return}const open=latestOpenIteration();if(!t&&!open){toast('当前没有进行中的批次，请先创建或重新打开一个批次');openSettings('iterations');return}editingTaskId=id||'';$('editDialogTitle').textContent=t?'编辑需求':'新增需求';$('editForm').reset();$('taskTitle').value=t?.title||'';
 $('taskIteration').innerHTML=orderedIterations().filter(b=>!b.is_closed||b.id===t?.iteration_id).map(b=>`<option value="${escapeHtml(b.id)}">${escapeHtml(b.name)}${b.is_closed?'（已结束）':''}</option>`).join('');$('taskIteration').value=t?.iteration_id||(!iteration()?.is_closed&&iteration()?iteration().id:open.id);
 $('taskCategory').innerHTML=editorCategories(t?.category);$('taskCategory').value=t?.category||categories.find(c=>c.is_active)?.name||'';$('taskPriority').value=t?.priority||'normal';$('taskDescription').value=t?.description||'';$('taskLinks').value=(t?.links||[]).join('\n');$('taskDue').value=t?.due_date||'';$('taskAssignee').innerHTML='<option value="">暂不指定</option>'+members.filter(m=>['developer','operator'].includes(m.role)).map(m=>`<option value="${escapeHtml(m.email)}">${escapeHtml(m.email)}</option>`).join('');$('taskAssignee').value=t?.assignee_email||'';const pairs=[...(t?.sources||[]).map(p=>({p,k:'sources'})),...(t?.references||[]).map(p=>({p,k:'references'}))];await ensureSigned(pairs.map(x=>x.p));$('retainedImages').innerHTML=pairs.map(x=>`<label><input type="checkbox" data-keep="${escapeHtml(x.k)}" value="${escapeHtml(x.p)}" checked><img src="${escapeHtml(signedSrc(x.p))}" alt="已上传参考图">保留</label>`).join('');openModal('editDialog')}
async function saveTask(e){e.preventDefault();if(!canEdit())return;const id=editingTaskId,button=$('saveTaskBtn'),title=$('taskTitle').value.trim(),category=$('taskCategory').value,priority=$('taskPriority').value,iteration_id=$('taskIteration').value,assignee=$('taskAssignee').value||null,due=$('taskDue').value||null,description=$('taskDescription').value.trim(),links=$('taskLinks').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(safeUrl);if(!title||links.some(x=>!x)){toast('标题必填，参考链接需要以 http:// 或 https:// 开头');return}button.disabled=true;isBusy=true;try{const t=id?taskById(id):null;const sources=t?(t.sources||[]).filter(path=>[...document.querySelectorAll('#retainedImages input[data-keep="sources"]:checked')].some(e=>e.value===path)):[];const references=t?(t.references||[]).filter(path=>[...document.querySelectorAll('#retainedImages input[data-keep="references"]:checked')].some(e=>e.value===path)):[];const values={title,category,priority,iteration_id,description,links,assignee_email:assignee,due_date:due,sources,references};let taskId=id;
 if(id){const {error}=await db.from('requirements').update(values).eq('id',id).eq('project_id',projectId);if(error)throw error}
 else{const sortOrder=Math.max(0,...requirements.map(t=>t.sort_order||0))+100;const {data,error}=await db.from('requirements').insert({...values,project_id:projectId,sort_order:sortOrder,source:'协作新增',is_custom:true}).select('id').single();if(error)throw error;taskId=data.id}
 const files=$('taskImages').files;if(files.length){const paths=await uploadImages(files);const {error}=await db.from('requirements').update({sources:[...sources,...paths]}).eq('id',taskId).eq('project_id',projectId);if(error)throw error}
 closeModal('editDialog');await loadProject(projectId,{quiet:true});if(activeTaskId===taskId){renderDrawer();await ensureSigned(detailImages(taskById(taskId)));renderDrawerBody()}toast(id?'需求已保存':'需求添加成功')
 }catch(err){fail(err,'保存需求失败')}finally{isBusy=false;button.disabled=false}}
async function confirmTaskWithdrawal(){const t=taskById(activeTaskId);if(!t||!canEdit())return;const withdraw=!t.is_withdrawn;confirmDialog(withdraw?'撤回需求':'恢复需求',withdraw?'撤回后该任务将停止进度操作，但不会删除需求和历史记录。':'确定恢复该需求，继续安排开发？',async()=>{const {error}=await db.from('requirements').update({is_withdrawn:withdraw}).eq('id',t.id).eq('project_id',projectId);if(error)throw error;await loadProject(projectId,{quiet:true});renderDrawer();toast(withdraw?'已撤回需求':'需求已恢复')})}
async function deleteTask(){const t=taskById(activeTaskId);if(!t||!isAdmin())return;confirmDialog('永久删除需求',`确认永久删除「${t.title}」及相关进度历史？此操作不可撤销。`,async()=>{const {error}=await db.from('requirements').delete().eq('id',t.id).eq('project_id',projectId);if(error)throw error;closeDrawer();await loadProject(projectId,{quiet:true});toast('需求已删除')})}
async function updatePriority(id,value,select){if(!canEdit()||!Object.hasOwn(PRIORITY,value))return;const t=taskById(id);if(!t||t.priority===value)return;select.disabled=true;isBusy=true;try{const {error}=await db.from('requirements').update({priority:value}).eq('id',id).eq('project_id',projectId);if(error)throw error;await loadProject(projectId,{quiet:true});if(activeTaskId===id)renderDrawer();toast(`已设为「${PRIORITY[value]}」，排序已自动更新`)}catch(e){fail(e,'设置优先级失败');renderTaskList()}finally{isBusy=false}}
async function positionTask(id,n){const t=taskById(id),b=iterations.find(x=>x.id===t?.iteration_id);if(!canEdit()||!t||b?.is_closed)return;isBusy=true;try{const {error}=await db.rpc('board_set_task_position',{p_task:id,p_position:n});if(error)throw error;state.sort='plan';$('sortSelect').value='plan';await loadProject(projectId,{quiet:true});closeModal('moveDialog');toast('当前批次内的排序已保存')}catch(e){fail(e,'调整排序失败')}finally{isBusy=false}}
function openPositionDialog(id){const t=taskById(id);if(!canEdit()||!t||iterations.find(b=>b.id===t.iteration_id)?.is_closed)return;moveTaskId=id;$('moveTaskName').textContent=`${t.title} · ${iterationName(t.iteration_id)} · ${PRIORITY[t.priority]||'普通'}组`;$('movePosition').value=taskGroup(t).findIndex(x=>x.id===id)+1;$('movePosition').max=taskGroup(t).length;openModal('moveDialog')}
function openSettings(tab='projects'){if(!canManage()&&!(tab==='projects'&&canCreateProject()))return;state.settingsTab=tab;renderSettings();openModal('settingsDialog');closeSidebar()}
function renderSettings(){document.querySelectorAll('#settingsTabs button').forEach(b=>b.classList.toggle('active',b.dataset.settings===state.settingsTab));if(state.settingsTab==='categories')renderSettingsCategories();else if(state.settingsTab==='members')renderSettingsMembers();else if(state.settingsTab==='iterations')renderSettingsIterations();else renderSettingsProjects()}
function renderSettingsIterations(){if(!canEdit())return;const list=orderedIterations();$('settingsBody').innerHTML=`<div class="role-explainer">同一个长期项目可以分多轮提需求。不同批次独立查看进度与排序；已结束批次保留历史，不再接收新需求。旧需求默认在「初始需求（升级前）」。</div><div class="settings-list">${list.map(b=>{const n=requirements.filter(t=>t.iteration_id===b.id).length;const edit=editingIterationId===b.id;return `<div class="settings-item"><div class="batch-settings-info">${edit?`<form data-form="iteration-rename" data-id="${b.id}" class="batch-rename-form"><input name="name" maxlength="80" class="inline-input" required value="${escapeHtml(b.name)}"><button type="submit" class="btn btn-dark">保存</button></form>`:`<h4>${escapeHtml(b.name)}</h4>`}<p>${b.is_closed?'已结束':'进行中'} · ${n} 条需求 · 创建 ${toDate(b.created_at)}</p>${b.description?`<p>${escapeHtml(b.description)}</p>`:''}</div><div class="settings-item-right"><button class="btn btn-light" type="button" data-iteration-open="${b.id}">查看</button><button class="btn btn-light" type="button" data-iteration-edit="${b.id}">改名</button><button class="btn ${b.is_closed?'btn-light':'btn-outline-red'}" type="button" data-iteration-toggle="${b.id}">${b.is_closed?'重新开启':'结束批次'}</button></div></div>`}).join('')}</div><form class="sub-form" data-form="iteration-create"><h4>创建下一批需求</h4><div class="field"><label for="newIterationName">批次名称 *</label><input id="newIterationName" required maxlength="80" placeholder="例如：2026 年 11 月 · 第二批"></div><div class="field"><label for="newIterationDescription">批次说明（可选）</label><textarea id="newIterationDescription" maxlength="600" rows="2" placeholder="例如：黑五活动后的产品页面调整"></textarea></div><button class="btn btn-dark" type="submit">${icon('plus')}创建批次并切换</button></form>`}
function renderSettingsProjects(){const current=project();$('settingsBody').innerHTML=`<div class="role-explainer">你可以管理自己负责的项目。运营可创建多个项目，但不能访问其他运营的项目；归档需要全局管理员。</div><div class="settings-list">${projects.map(p=>`<div class="settings-item"><div><h4>${escapeHtml(p.name)}${p.id===projectId?' · 当前项目':''}</h4><p>${escapeHtml(p.description||'暂无项目说明')}</p></div><div class="settings-item-right"><button type="button" class="btn btn-light" data-project-open="${p.id}">打开</button>${isAdmin()?`<button type="button" class="btn btn-light" data-project-archive="${p.id}">${p.is_archived?'恢复':'归档'}</button>`:''}</div></div>`).join('')}</div>${canEdit()?`<form class="sub-form" data-form="project-edit"><h4>编辑当前项目</h4><div class="field"><label for="settingsProjectName">项目名称</label><input id="settingsProjectName" maxlength="100" required value="${escapeHtml(current?.name||'')}"></div><div class="field"><label for="settingsProjectDesc">项目说明</label><textarea id="settingsProjectDesc" maxlength="500" rows="2">${escapeHtml(current?.description||'')}</textarea></div><button class="btn btn-light" type="submit">保存项目资料</button></form>`:''}${canCreateProject()?`<form class="sub-form" data-form="project-create"><h4>新建项目</h4><div class="field"><label for="settingsNewProject">项目名称 *</label><input id="settingsNewProject" maxlength="100" required placeholder="例如：WOSADO 官网升级"></div><div class="field"><label for="settingsNewDesc">项目说明</label><input id="settingsNewDesc" maxlength="500" placeholder="可填写项目目标或客户名称"></div><button type="submit" class="btn btn-dark">${icon('plus')}创建项目</button></form>`:''}`}
function renderSettingsCategories(){if(!canEdit())return;const list=allCategories().filter(c=>!String(c.id).startsWith('legacy:'));$('settingsBody').innerHTML=`<div class="role-explainer">分类只影响当前项目。改名会同步更新此分类下的所有需求，停用不会删除历史需求。</div><div class="settings-list">${list.map((c,i)=>{const used=requirements.filter(t=>t.category===c.name).length;const edit=editingCategoryId===c.id;return `<div class="settings-item"><div style="flex:1">${edit?`<form data-form="category-rename" data-id="${c.id}" style="display:flex;gap:6px"><input class="inline-input" name="name" required maxlength="60" value="${escapeHtml(c.name)}"><button type="submit" class="btn btn-dark">保存</button></form>`:`<h4>${escapeHtml(c.name)}</h4>`}<p>${used} 条需求 · ${c.is_active?'启用中':'已停用'}</p></div><div class="settings-item-right"><button class="btn btn-light" data-category-move="${c.id}" data-offset="-1" type="button" ${i===0?'disabled':''}>↑</button><button class="btn btn-light" data-category-move="${c.id}" data-offset="1" type="button" ${i===list.length-1?'disabled':''}>↓</button><button class="btn btn-light" type="button" data-category-rename="${c.id}">改名</button><button class="btn btn-light" data-category-toggle="${c.id}" type="button">${c.is_active?'停用':'启用'}</button><button class="btn btn-outline-red" type="button" data-category-delete="${c.id}" ${used?'disabled title="该分类仍有关联需求"':''}>删除</button></div></div>`}).join('')||'<p class="settings-msg">当前项目还没有分类。</p>'}</div><form class="sub-form" data-form="category-create"><h4>添加新分类</h4><div class="field"><label for="settingsNewCategory">分类名称</label><input id="settingsNewCategory" required maxlength="60" placeholder="例如：首页设计、功能优化、促销活动"></div><button class="btn btn-dark" type="submit">添加分类</button></form>`}
function renderSettingsMembers(){if(!canManage())return;const editable=canManage();$('settingsBody').innerHTML=`<div class="role-explainer">项目成员只拥有当前项目的权限。运营可以管理开发和只读成员；只有全局管理员能任命、移除另一位运营负责人。</div><div class="settings-list">${members.map(m=>{const locked=m.role==='operator'&&!isAdmin();return `<div class="settings-item"><div><h4>${escapeHtml(m.email)}</h4><p>${ROLE_NAME[m.role]||m.role} · ${toDate(m.created_at)} 加入</p></div><div class="settings-item-right">${editable?`<select aria-label="成员角色" data-member-role="${escapeHtml(m.email)}" ${locked?'disabled title="只有全局管理员能调整运营负责人"':''}>${(isAdmin()?['operator','developer','viewer']:['developer','viewer']).map(role=>`<option value="${role}" ${role===m.role?'selected':''}>${ROLE_NAME[role]}</option>`).join('')}</select><button type="button" class="btn btn-outline-red" data-member-remove="${escapeHtml(m.email)}" ${locked?'disabled':''}>移除</button>`:''}</div></div>`}).join('')||'<p class="settings-msg">这个项目还没有分配其他团队成员。</p>'}</div><form class="sub-form" data-form="member-add"><h4>添加项目成员</h4><div class="form-pair"><div class="field"><label for="settingsNewEmail">工作邮箱</label><input type="email" id="settingsNewEmail" required placeholder="colleague@company.com"></div><div class="field"><label for="settingsNewRole">项目角色</label><select id="settingsNewRole">${(isAdmin()?['operator','developer','viewer']:['developer','viewer']).map(role=>`<option value="${role}">${ROLE_NAME[role]}</option>`).join('')}</select></div></div><button class="btn btn-dark" type="submit">添加成员</button><p class="settings-msg">这里授予的是项目访问权，尚未注册的成员仍需在登录页注册并完成邮箱验证。</p></form>`}
async function submitSettingsForm(e){const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();if(!canManage())return;const b=form.querySelector('[type="submit"]');if(b)b.disabled=true;isBusy=true;try{if(form.dataset.form==='project-create'){
 const name=$('settingsNewProject').value.trim(),description=$('settingsNewDesc').value.trim();const {data,error}=await db.rpc('board_create_project',{p_name:name,p_description:description});if(error)throw error;await loadAccess();closeModal('settingsDialog');await switchProject(data);toast('项目已创建，你是这个项目的负责人');
 }else if(form.dataset.form==='project-edit'){
 const name=$('settingsProjectName').value.trim(),description=$('settingsProjectDesc').value.trim();const {error}=await db.from('board_projects').update({name,description}).eq('id',projectId);if(error)throw error;await loadAccess();renderAll();renderSettings();toast('项目资料已更新');
 }else if(form.dataset.form==='category-create'){
 const name=$('settingsNewCategory').value.trim();const {error}=await db.from('board_categories').insert({project_id:projectId,name,sort_order:Math.max(0,...categories.map(c=>c.sort_order||0))+100});if(error)throw error;await loadProject(projectId,{quiet:true});renderSettings();toast('分类已添加');
 }else if(form.dataset.form==='category-rename'){
 const name=form.querySelector('[name="name"]').value.trim();const {error}=await db.from('board_categories').update({name}).eq('project_id',projectId).eq('id',form.dataset.id);if(error)throw error;editingCategoryId='';await loadProject(projectId,{quiet:true});renderSettings();toast('分类名称已更新');
 }else if(form.dataset.form==='iteration-create'){
 const name=$('newIterationName').value.trim(),description=$('newIterationDescription').value.trim();const {data,error}=await db.from('board_iterations').insert({project_id:projectId,name,description}).select('id').single();if(error)throw error;state.iteration=data.id;await loadProject(projectId,{quiet:true});closeModal('settingsDialog');toast('新批次已创建，后续需求默认添加到这一批');
 }else if(form.dataset.form==='iteration-rename'){
 const name=form.querySelector('[name="name"]').value.trim();const {error}=await db.from('board_iterations').update({name}).eq('id',form.dataset.id).eq('project_id',projectId);if(error)throw error;editingIterationId='';await loadProject(projectId,{quiet:true});renderSettings();toast('批次名称已更新');
 }else if(form.dataset.form==='member-add'){
 const email=$('settingsNewEmail').value.trim().toLowerCase(),role=$('settingsNewRole').value;const {error}=await db.rpc('board_assign_member',{p_project:projectId,p_email:email,p_role:role});if(error)throw error;await loadProject(projectId,{quiet:true});renderSettings();toast('成员已获当前项目的访问权限')
 }}catch(err){fail(err,'保存设置失败')}finally{isBusy=false;if(b)b.disabled=false}}
async function categorySettingAction(btn){const id=btn.dataset.categoryRename||btn.dataset.categoryToggle||btn.dataset.categoryDelete||btn.dataset.categoryMove;const c=categories.find(x=>x.id===id);if(!c||!canEdit())return;if(btn.hasAttribute('data-category-rename')){editingCategoryId=id;renderSettings();return}let response;
 try{if(btn.hasAttribute('data-category-toggle'))response=await db.from('board_categories').update({is_active:!c.is_active}).eq('project_id',projectId).eq('id',id);
 else if(btn.hasAttribute('data-category-delete')){if(requirements.some(t=>t.category===c.name)){toast('先将需求移动到其他分类');return}return confirmDialog('删除分类',`确定删除空分类「${c.name}」？`,async()=>{const {error}=await db.from('board_categories').delete().eq('project_id',projectId).eq('id',id);if(error)throw error;await loadProject(projectId,{quiet:true});renderSettings();toast('分类已删除')})}
 else if(btn.hasAttribute('data-category-move')){const pos=allCategories().findIndex(x=>x.id===id)+1+Number(btn.dataset.offset);response=await db.rpc('board_set_category_position',{p_category:id,p_position:pos})}
 if(response?.error)throw response.error;await loadProject(projectId,{quiet:true});renderSettings();toast('分类设置已更新')
 }catch(e){fail(e,'分类设置失败')}}
async function iterationSettingAction(btn){if(!canEdit())return;const id=btn.dataset.iterationEdit||btn.dataset.iterationToggle||btn.dataset.iterationOpen;const b=iterations.find(x=>x.id===id);if(!b)return;if(btn.hasAttribute('data-iteration-open')){state.iteration=id;closeModal('settingsDialog');renderAll();return}if(btn.hasAttribute('data-iteration-edit')){editingIterationId=id;renderSettings();return}if(btn.hasAttribute('data-iteration-toggle')){const next=!b.is_closed;const unfinished=requirements.filter(t=>t.iteration_id===id&&!t.is_withdrawn&&status(t.id)!=='done').length;confirmDialog(next?'结束这一批需求？':'重新开启这一批？',next?`本批次有 ${unfinished} 项未通过验收。结束后仍能查看和修改历史需求，但不能新增需求到此批。`:`重新开启「${b.name}」后可以继续往本批次添加需求。`,async()=>{const {error}=await db.from('board_iterations').update({is_closed:next}).eq('project_id',projectId).eq('id',id);if(error)throw error;await loadProject(projectId,{quiet:true});renderSettings();toast(next?'批次已结束，历史任务保留':'批次已重新开启')})}}
async function memberRoleChanged(select){if(!canManage())return;const email=select.dataset.memberRole,role=select.value;isBusy=true;try{const {error}=await db.rpc('board_assign_member',{p_project:projectId,p_email:email,p_role:role});if(error)throw error;await loadProject(projectId,{quiet:true});renderSettings();toast('成员角色已修改')}catch(e){fail(e,'修改角色失败');renderSettings()}finally{isBusy=false}}
function confirmDialog(title,message,callback){$('confirmTitle').textContent=title;$('confirmMessage').textContent=message;confirmAction=callback;openModal('confirmDialog')}
async function settingsActionClick(e){const btn=e.target.closest('button');if(!btn)return;const projectOpen=btn.dataset.projectOpen;if(projectOpen){closeModal('settingsDialog');await switchProject(projectOpen);return}const archive=btn.dataset.projectArchive;if(archive&&isAdmin()){
 const p=projects.find(x=>x.id===archive);if(!p)return;confirmDialog(p.is_archived?'恢复项目':'归档项目',p.is_archived?`恢复 ${p.name} 后，项目成员重新获得访问权。`:`归档「${p.name}」后，普通项目成员将暂时无法查看。`,async()=>{const {error}=await db.from('board_projects').update({is_archived:!p.is_archived}).eq('id',p.id);if(error)throw error;await loadAccess();if(!projects.some(x=>x.id===projectId)){await switchProject(projects[0]?.id)}else renderAll();renderSettings();toast('项目状态已更新')});return}
 if(Object.keys(btn.dataset).some(k=>k.startsWith('iteration'))){await iterationSettingAction(btn);return}
 if(Object.keys(btn.dataset).some(k=>k.startsWith('category'))){await categorySettingAction(btn);return}
 const remove=btn.dataset.memberRemove;if(remove){confirmDialog('移除项目成员',`把 ${remove} 移出当前项目？他在本项目的待办将自动解除分配，不会影响其他项目或账号。`,async()=>{const {error}=await db.rpc('board_remove_member',{p_project:projectId,p_email:remove});if(error)throw error;await loadProject(projectId,{quiet:true});renderSettings();toast('成员已移出项目')})}}
function renderReport(){const s=stats(),tasks=batchTasks();$('reportTitle').textContent=`${project()?.name||''} · ${iteration()?.name||'全部批次'} · 需求报表`;const risks=unwithdrawn().filter(t=>prog(t.id).is_blocked||isOverdue(t)).sort((a,b)=>(isOverdue(b)?1:0)-(isOverdue(a)?1:0)).slice(0,12);
 $('reportBody').innerHTML=`<div class="role-explainer">报表范围：${escapeHtml(iteration()?.name||'全部批次（历史汇总）')}。可以在首页切换批次后重新生成单批次报表。</div><div class="report-tiles">${[['全部需求',s.total],['进行中',s.doing],['待验收',s.review],['已完成',s.done],['阻塞中',s.blocked],['逾期任务',s.overdue]].map(x=>`<div class="report-tile"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><h4 class="report-subtitle">需要关注的问题 ${risks.length?`（${risks.length}）`:''}</h4>${risks.length?`<div style="overflow:auto"><table class="report-table"><thead><tr><th>需求</th><th>批次</th><th>进度</th><th>负责人</th><th>风险</th></tr></thead><tbody>${risks.map(t=>`<tr><td>${escapeHtml(t.title)}</td><td>${escapeHtml(iterationName(t.iteration_id))}</td><td>${STATUS_NAME[status(t.id)]}</td><td>${escapeHtml(t.assignee_email||'未分配')}</td><td>${prog(t.id).is_blocked?'阻塞 ':''}${isOverdue(t)?'逾期':''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="settings-msg">目前没有阻塞或逾期的任务。</p>'}<h4 class="report-subtitle">需求明细（${tasks.length}）</h4><div style="overflow:auto;max-height:320px"><table class="report-table"><thead><tr><th>批次</th><th>组内序号</th><th>需求</th><th>优先级</th><th>状态</th><th>负责人</th></tr></thead><tbody>${manualTasks().map(t=>`<tr><td>${escapeHtml(iterationName(t.iteration_id))}</td><td>${taskGroup(t).findIndex(x=>x.id===t.id)+1}</td><td>${escapeHtml(t.title)}</td><td>${PRIORITY[t.priority]||'普通'}</td><td>${t.is_withdrawn?'已撤回':STATUS_NAME[status(t.id)]}</td><td>${escapeHtml(t.assignee_email||'—')}</td></tr>`).join('')}</tbody></table></div><p class="settings-msg">完成率仅统计未撤回需求；只读成员也可导出授权批次的 CSV。</p>`}
function csvEscape(value){const s=String(value??'');return '"'+(/^[=+@-]/.test(s)?"'"+s:s).replace(/"/g,'""')+'"'}
async function downloadCsv(){try{const {data:notes,error}=await db.from('board_activity').select('requirement_id,body,kind,created_at,actor_email').eq('project_id',projectId).order('created_at',{ascending:false}).limit(1000);if(error)throw error;const latest=new Map();for(const x of notes||[]){if(x.body&&x.body.trim()&&!latest.has(x.requirement_id))latest.set(x.requirement_id,`${x.body} (${x.actor_email}, ${toTime(x.created_at)})`)}
const ordered=manualTasks();const header=['项目','需求批次','组内执行顺序','需求标题','分类','优先级','进度','阻塞','是否撤回','开发负责人','计划完成日期','创建日期','最近更新','最近反馈','原始备注','需求说明','参考链接'];const rows=ordered.map(t=>[project()?.name,iterationName(t.iteration_id),taskGroup(t).findIndex(x=>x.id===t.id)+1,t.title,t.category,PRIORITY[t.priority]||'普通',STATUS_NAME[status(t.id)],prog(t.id).is_blocked?'是':'否',t.is_withdrawn?'是':'否',t.assignee_email||'',t.due_date||'',t.created_at||'',prog(t.id).updated_at||t.updated_at||'',latest.get(t.id)||'',prog(t.id).note||'',t.description||'',(t.links||[]).join(' ; ')]);const csv='\ufeff'+[header,...rows].map(row=>row.map(csvEscape).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const fileUrl=URL.createObjectURL(blob),a=document.createElement('a');a.href=fileUrl;a.download=`${project()?.name||'需求'}_${iteration()?.name||'全部批次'}_${TODAY()}.csv`.replace(/[\/<>:"|?*]/g,'_');document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(fileUrl),1500);toast('当前批次的报表已导出')}
catch(e){fail(e,'导出报表失败')}}
function bindEvents(){
 $('menuToggle').addEventListener('click',openSidebar);$('sidebarShade').addEventListener('click',closeSidebar);
 $('projectNav').addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(b)switchProject(b.dataset.project)});
 $('assetsNav').addEventListener('click',()=>{state.category='assets';renderCategoryNav();renderTaskList();closeSidebar()});
 $('categoryNav').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;state.category=b.dataset.category;renderCategoryNav();renderTaskList();closeSidebar()});
 $('mobileProjectSelect').addEventListener('change',e=>switchProject(e.target.value));
 $('iterationSelect').addEventListener('change',e=>{state.iteration=e.target.value;state.category='all';renderAll()});
 $('iterationNew').addEventListener('click',()=>{openSettings('iterations');$('newIterationName')?.scrollIntoView({block:'nearest'});$('newIterationName')?.focus()});
 $('iterationManage').addEventListener('click',()=>openSettings('iterations'));
 $('refreshBtn').addEventListener('click',async()=>{try{await loadAccess();if(!projects.some(p=>p.id===projectId)){showScreen('denied');return}await loadProject(projectId,{quiet:true});toast('最新数据已同步')}catch(e){fail(e,'同步失败')}});
 $('createProjectQuick').addEventListener('click',()=>openSettings('projects'));
 $('sidebarSettings').addEventListener('click',()=>openSettings('projects'));
 $('settingsBtn').addEventListener('click',()=>openSettings('projects'));
 $('addTaskBtn').addEventListener('click',()=>openEditor());
 $('reportBtn').addEventListener('click',()=>{renderReport();openModal('reportDialog')});$('downloadReport').addEventListener('click',downloadCsv);
 $('viewTabs').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;state.view=b.dataset.view;renderViewTabs();renderTaskList()});
 $('searchInput').addEventListener('input',e=>{state.query=e.target.value;renderTaskList()});
 $('statusFilter').addEventListener('change',e=>{state.status=e.target.value;renderTaskList()});
 $('sortSelect').addEventListener('change',e=>{state.sort=e.target.value;renderTaskList()});
 $('taskList').addEventListener('change',async e=>{const ctl=e.target.closest('[data-priority]');if(ctl)await updatePriority(ctl.dataset.priority,ctl.value,ctl)});
 $('taskList').addEventListener('click',async e=>{const asset=e.target.closest('[data-asset-preview]');if(asset){previewPaths=assets.map(x=>x.path);previewIndex=previewPaths.indexOf(asset.dataset.assetPreview);await paintImage();openModal('previewDialog');return}if(e.target.closest('[data-empty-add]')){openEditor();return}const move=e.target.closest('[data-move]');if(move){openPositionDialog(move.dataset.move);return}const open=e.target.closest('[data-open]');if(open)await openTask(open.dataset.open)});
 $('taskList').addEventListener('dragstart',e=>{const card=e.target.closest('[data-task-card]');if(!card||!canReorder()||e.target.closest('select,input,button,a')){e.preventDefault();return}dragTaskId=card.dataset.taskCard;card.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragTaskId)});
 $('taskList').addEventListener('dragend',()=>{dragTaskId='';document.querySelectorAll('.task-card.dragging').forEach(c=>c.classList.remove('dragging'))});
 $('taskList').addEventListener('dragover',e=>{if(dragTaskId&&canReorder()&&e.target.closest('[data-task-card]'))e.preventDefault()});
 $('taskList').addEventListener('drop',async e=>{const card=e.target.closest('[data-task-card]');if(!card||!dragTaskId||!canReorder())return;e.preventDefault();const id=dragTaskId,target=card.dataset.taskCard;dragTaskId='';if(id===target)return;const a=taskById(id),b=taskById(target);if(a?.iteration_id!==b?.iteration_id||a?.priority!==b?.priority){toast('只能在同一个批次、同一优先级内调整顺序');return}await positionTask(id,taskGroup(a).findIndex(t=>t.id===target)+1)});
 $('drawerBackdrop').addEventListener('click',closeDrawer);$('drawerClose').addEventListener('click',closeDrawer);
 $('drawerTabs').addEventListener('click',async e=>{const b=e.target.closest('[data-tab]');if(!b)return;if(b.dataset.tab==='activity')await openActivity();else{detailTab='details';renderDrawer()}});
 $('drawerBody').addEventListener('click',async e=>{const img=e.target.closest('[data-image]');if(img)await openImage(img.dataset.image)});
 $('drawerActions').addEventListener('click',async e=>{const q=e.target.closest('[data-quick]');if(q){await quickStatus(q.dataset.quick);return}const edit=e.target.closest('[data-drawer-edit]');if(edit){await openEditor(edit.dataset.drawerEdit);return}const move=e.target.closest('[data-drawer-move]');if(move){openPositionDialog(move.dataset.drawerMove);return}if(e.target.closest('[data-return]')){await openActivity();const select=$('progressStatus');if(select)select.value='doing';const note=$('progressMessage');if(note){note.placeholder='请填写退回原因，开发会在历史记录中看到';note.focus()}return}if(e.target.closest('[data-withdraw]')){await confirmTaskWithdrawal();return}if(e.target.closest('[data-delete]')){await deleteTask();return}if(e.target.closest('#drawerHistory'))await openActivity()});
 $('editForm').addEventListener('submit',saveTask);$('moveForm').addEventListener('submit',async e=>{e.preventDefault();const n=Number($('movePosition').value);if(Number.isInteger(n)&&n>=1&&moveTaskId)await positionTask(moveTaskId,n)});
 $('settingsTabs').addEventListener('click',e=>{const b=e.target.closest('[data-settings]');if(!b)return;state.settingsTab=b.dataset.settings;editingCategoryId='';editingIterationId='';renderSettings()});
 $('settingsBody').addEventListener('submit',submitSettingsForm);$('settingsBody').addEventListener('click',settingsActionClick);
 $('settingsBody').addEventListener('change',e=>{const s=e.target.closest('[data-member-role]');if(s)memberRoleChanged(s)});
 $('confirmYes').addEventListener('click',async()=>{if(!confirmAction)return;const fn=confirmAction;confirmAction=null;const btn=$('confirmYes');btn.disabled=true;isBusy=true;try{await fn();closeModal('confirmDialog')}catch(e){fail(e,'提交失败')}finally{isBusy=false;btn.disabled=false}});
 document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>closeModal(b.dataset.close)));
 $('previewPrev').addEventListener('click',async()=>{previewIndex=Math.max(0,previewIndex-1);await paintImage()});
 $('previewNext').addEventListener('click',async()=>{previewIndex=Math.min(previewPaths.length-1,previewIndex+1);await paintImage()});
 $('authForm').addEventListener('submit',async e=>{e.preventDefault();const email=$('authEmail').value.trim().toLowerCase(),password=$('authPassword').value,btn=$('authSubmit');btn.disabled=true;$('authError').textContent='';try{if(authMode==='login'){
 const {data,error}=await db.auth.signInWithPassword({email,password});if(error)throw error;await authRoute(data.session);
 }else{const {data,error}=await db.auth.signUp({email,password,options:{emailRedirectTo:location.origin}});if(error)throw error;if(data.session){await authRoute(data.session)}else{$('authError').style.color='#307960';$('authError').textContent='注册已提交，请先检查邮箱完成验证，然后返回登录。';authMode='login';$('authHeading').textContent='登录项目看板';$('authSubmit').textContent='登录看板';$('authToggle').textContent='首次使用？注册账号'}}
 }catch(err){$('authError').style.color='#b04745';$('authError').textContent=err?.message||'登录失败'}finally{btn.disabled=false}});
 $('authToggle').addEventListener('click',()=>{authMode=authMode==='login'?'signup':'login';$('authHeading').textContent=authMode==='login'?'登录项目看板':'注册团队账号';$('authSubmit').textContent=authMode==='login'?'登录看板':'注册账号';$('authToggle').textContent=authMode==='login'?'首次使用？注册账号':'已有账号？返回登录';$('authError').textContent='';$('authPassword').autocomplete=authMode==='login'?'current-password':'new-password'});
 $('retryAccess').addEventListener('click',async()=>{try{await authRoute({user:me})}catch(e){fail(e)}});
 async function logout(){if(!db)return;await db.auth.signOut();resetData();showScreen('auth')}
 $('logoutBtn').addEventListener('click',logout);$('deniedLogout').addEventListener('click',logout);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){if(!$('taskDrawer').hidden)closeDrawer();else closeSidebar()}});
}
async function init(){bindEvents();showScreen('auth');const cfg=window.BOARD_CONFIG||{};if(!/^https:\/\//.test(cfg.supabaseUrl||'')||!cfg.supabaseKey){$('authError').textContent='缺少 Supabase 配置。请先在 Vercel 设置 SUPABASE_URL 和 SUPABASE_PUBLISHABLE_KEY。';$('authSubmit').disabled=true;return}if(!window.supabase?.createClient){$('authError').textContent='Supabase SDK 没有加载，请检查网络连接。';$('authSubmit').disabled=true;return}
 db=window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
 db.auth.onAuthStateChange((event,session)=>{if(['SIGNED_IN','SIGNED_OUT','INITIAL_SESSION'].includes(event))setTimeout(()=>{if(session?.user?.id!==sessionId)authRoute(session)},0)});
 const {data,error}=await db.auth.getSession();if(error)throw error;await authRoute(data.session);
}
init().catch(e=>{console.error(e);$('authError').textContent='初始化失败：'+(e?.message||e)});
})();
